INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7567697, 1214473, 73942, '<td valign="top">awe, this is so perfect for this challenge</td>', 'awe, this is so perfect for this challenge', '2018-05-04 09:28:52.000000', NULL, 1),
(7567698, 1214484, 73942, '<td valign="top">beautiful</td>', 'beautiful', '2018-05-04 09:30:17.000000', NULL, 1),
(7567699, 1214448, 73942, '<td valign="top">lovely</td>', 'lovely', '2018-05-04 09:30:52.000000', NULL, 1),
(7567739, 1214466, 97225, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2018-05-04 18:43:46.000000', NULL, 1),
(7567745, 1214459, 30982, '<td valign="top">Lovely!  Shez loved her critters and her closeups!</td>', 'Lovely!  Shez loved her critters and her closeups!', '2018-05-04 21:13:33.000000', NULL, 1),
(7567746, 1214450, 30982, '<td valign="top">Fine shallow depth of field here.  Nicely done.</td>', 'Fine shallow depth of field here.  Nicely done.', '2018-05-04 21:13:51.000000', NULL, 1),
(7567747, 1214449, 30982, '<td valign="top">Very much her style!  Square crop, close in, warm colors!</td>', 'Very much her style!  Square crop, close in, warm colors!', '2018-05-04 21:14:10.000000', NULL, 1),
(7567748, 1214438, 30982, '<td valign="top">I like the stylization!  She loved to experiment with her processing.  I think her challenges with her eyesight let her try things more "conventional" photogs might have not been brave enough to take on.  Well done.</td>', 'I like the stylization!  She loved to experiment with her processing.  I think her challenges with her eyesight let her try things more "conventional" photogs might have not been brave enough to take on.  Well done.', '2018-05-04 21:14:55.000000', NULL, 1),
(7567749, 1214291, 30982, '<td valign="top">A very nice tribute!</td>', 'A very nice tribute!', '2018-05-04 21:15:07.000000', NULL, 1),
(7567750, 1214448, 30982, '<td valign="top">Ah, you''ve captured the color of her beloved agave beautifully!</td>', 'Ah, you''ve captured the color of her beloved agave beautifully!', '2018-05-04 21:15:33.000000', NULL, 1),
(7567751, 1214203, 30982, '<td valign="top">She did love her square crops - it''s something I often associated with her work!</td>', 'She did love her square crops - it''s something I often associated with her work!', '2018-05-04 21:17:21.000000', NULL, 1),
(7567752, 1214460, 30982, '<td valign="top">Yes, she was all of those things and this is a marvelous warm, cheerful bright tribute!  Well done.</td>', 'Yes, she was all of those things and this is a marvelous warm, cheerful bright tribute!  Well done.', '2018-05-04 21:17:44.000000', NULL, 1),
(7567753, 1214484, 30982, '<td valign="top">Ah, this is really quite tender and dear.  Very appropriate for our Sherpet.</td>', 'Ah, this is really quite tender and dear.  Very appropriate for our Sherpet.', '2018-05-04 21:18:09.000000', NULL, 1),
(7567754, 1214088, 30982, '<td valign="top">She so enjoyed color!  She would approve!</td>', 'She so enjoyed color!  She would approve!', '2018-05-04 21:18:44.000000', NULL, 1),
(7567760, 1214342, 30982, '<td valign="top">She really did enjoy macro views of her succulents!  Nice use of the square crop as well.</td>', 'She really did enjoy macro views of her succulents!  Nice use of the square crop as well.', '2018-05-04 22:48:51.000000', NULL, 1),
(7567770, 1214434, 30982, '<td valign="top">Gentle and rich in color - she''d like this.</td>', 'Gentle and rich in color - she''d like this.', '2018-05-05 01:16:17.000000', NULL, 1),
(7567771, 1214343, 30982, '<td valign="top">Very Shez!  Squares and shells and color!</td>', 'Very Shez!  Squares and shells and color!', '2018-05-05 01:16:48.000000', NULL, 1),
(7567772, 1214471, 30982, '<td valign="top">I''m not sure I see Shez''s style here but she left us before we were allowed to work with textures - I think she might have enjoyed textures.</td>', 'I''m not sure I see Shez''s style here but she left us before we were allowed to work with textures - I think she might have enjoyed textures.', '2018-05-05 01:20:07.000000', NULL, 1),
(7567773, 1214489, 30982, '<td valign="top">This does remind me of a shot of hers!</td>', 'This does remind me of a shot of hers!', '2018-05-05 01:20:23.000000', NULL, 1),
(7567774, 1214339, 30982, '<td valign="top">A nice golden tribute.</td>', 'A nice golden tribute.', '2018-05-05 01:20:40.000000', NULL, 1),
(7567775, 1214453, 30982, '<td valign="top">Very much like her work - square crop and warm, radiant color!</td>', 'Very much like her work - square crop and warm, radiant color!', '2018-05-05 01:22:23.000000', NULL, 1),
(7567776, 1214444, 30982, '<td valign="top">A very nice take on a theme she enjoyed.</td>', 'A very nice take on a theme she enjoyed.', '2018-05-05 01:22:39.000000', NULL, 1),
(7567777, 1214277, 30982, '<td valign="top">Indeed - she truly liked the radiant beauty of nature.</td>', 'Indeed - she truly liked the radiant beauty of nature.', '2018-05-05 01:22:58.000000', NULL, 1),
(7567778, 1214487, 30982, '<td valign="top">Oh, she''d have enoyed this!  Such wonderful color!</td>', 'Oh, she''d have enoyed this!  Such wonderful color!', '2018-05-05 01:23:21.000000', NULL, 1),
(7567779, 1214428, 30982, '<td valign="top">She really enjoyed exploring nature in her yard, and beyond when she could.  Nice capture of these delicate flowers.</td>', 'She really enjoyed exploring nature in her yard, and beyond when she could.  Nice capture of these delicate flowers.', '2018-05-05 01:23:59.000000', NULL, 1),
(7567780, 1214446, 30982, '<td valign="top">Nice touch with going negative - Shez had some lovely inverted agave plants.  The stars are quite fitting as well!</td>', 'Nice touch with going negative - Shez had some lovely inverted agave plants.  The stars are quite fitting as well!', '2018-05-05 01:24:53.000000', NULL, 1),
(7567781, 1214483, 30982, '<td valign="top">Almost painterly!  She really did love vibrant color.</td>', 'Almost painterly!  She really did love vibrant color.', '2018-05-05 01:25:17.000000', NULL, 1),
(7567782, 1214435, 30982, '<td valign="top">So soft and rich - this is a wonderful tribute.</td>', 'So soft and rich - this is a wonderful tribute.', '2018-05-05 01:25:40.000000', NULL, 1),
(7567783, 1214466, 30982, '<td valign="top">Similar color scheme and approach when she did try her hand at blurs.  Very nice.</td>', 'Similar color scheme and approach when she did try her hand at blurs.  Very nice.', '2018-05-05 01:27:57.000000', NULL, 1),
(7567784, 1214133, 30982, '<td valign="top">This reminds of her puzzle pictures, where she''d arrange different objects in boxes or find the geometrics in things.  A big fan of geometrics, was our Shez!</td>', 'This reminds of her puzzle pictures, where she''d arrange different objects in boxes or find the geometrics in things.  A big fan of geometrics, was our Shez!', '2018-05-05 01:29:25.000000', NULL, 1),
(7567785, 1214473, 30982, '<td valign="top">Lovely, delicate tribute with the warmth and color she enjoyed sharing with us.</td>', 'Lovely, delicate tribute with the warmth and color she enjoyed sharing with us.', '2018-05-05 01:29:55.000000', NULL, 1),
(7567787, 1214436, 30982, '<td valign="top">Ah, vibrant and cheerful!  Almost a dance, in a way.</td>', 'Ah, vibrant and cheerful!  Almost a dance, in a way.', '2018-05-05 01:31:06.000000', NULL, 1),
(7567788, 1214480, 30982, '<td valign="top">A bit like a firework, and fascinating bokeh.  Almost as though you can see the crowd cheering in the distance.</td>', 'A bit like a firework, and fascinating bokeh.  Almost as though you can see the crowd cheering in the distance.', '2018-05-05 01:33:25.000000', NULL, 1),
(7567789, 1214474, 30982, '<td valign="top">Nice warm color and use of her signature square crop.</td>', 'Nice warm color and use of her signature square crop.', '2018-05-05 01:33:50.000000', NULL, 1),
(7567790, 1214451, 30982, '<td valign="top">A wonderful swath of color - practically glows!</td>', 'A wonderful swath of color - practically glows!', '2018-05-05 01:40:19.000000', NULL, 1),
(7567791, 1214458, 30982, '<td valign="top">She did enjoy her flowers and her yard very much - and enjoyed sharing those with us - thanks for doing the same!</td>', 'She did enjoy her flowers and her yard very much - and enjoyed sharing those with us - thanks for doing the same!', '2018-05-05 01:40:55.000000', NULL, 1),
(7567792, 1214217, 30982, '<td valign="top">Very much in her spirit - she seemed to like (and was very good at!) arranging objects like this.  Nice use of shells and the square crop, too.</td>', 'Very much in her spirit - she seemed to like (and was very good at!) arranging objects like this.  Nice use of shells and the square crop, too.', '2018-05-05 01:42:01.000000', NULL, 1),
(7567793, 1214397, 30982, '<td valign="top">Very nice color and detail - cropped as she would like it!</td>', 'Very nice color and detail - cropped as she would like it!', '2018-05-05 01:42:32.000000', NULL, 1),
(7567794, 1214465, 30982, '<td valign="top">Really lovely!!  She loved the nuance of plant form.  While she didn''t do B&amp;W often, when she did, she did it well.  She would appreciate this, I think!</td>', 'Really lovely!!  She loved the nuance of plant form.  While she didn''t do B&W often, when she did, she did it well.  She would appreciate this, I think!', '2018-05-05 01:43:55.000000', NULL, 1),
(7567958, 1214455, 62357, '<td valign="top">Fits the topic perfectly. Shez would have loved this</td>', 'Fits the topic perfectly. Shez would have loved this', '2018-05-07 22:15:28.000000', NULL, 1),
(7567959, 1214448, 62357, '<td valign="top">Beautiful tribute</td>', 'Beautiful tribute', '2018-05-07 22:15:47.000000', NULL, 1),
(7568063, 1214291, 35545, '<td valign="top">Shez would have loved this!</td>', 'Shez would have loved this!', '2018-05-08 17:21:34.000000', NULL, 1),
(7568119, 1214343, 42733, '<td valign="top">My favorite in this challenge!</td>', 'My favorite in this challenge!', '2018-05-09 13:38:02.000000', NULL, 1),
(7568120, 1214342, 42733, '<td valign="top">One of the best, in my view.</td>', 'One of the best, in my view.', '2018-05-09 13:38:21.000000', NULL, 1),
(7568121, 1214453, 42733, '<td valign="top">In my top 4.</td>', 'In my top 4.', '2018-05-09 13:38:32.000000', NULL, 1),
(7568122, 1214436, 42733, '<td valign="top">In my top 4.</td>', 'In my top 4.', '2018-05-09 13:38:40.000000', NULL, 1),
(7568212, 1214448, 173844, '<td valign="top">This image echoes Sherpet''s "Agave Blue" on her first profile page, so this is a very direct tribute.  Nevertheless, since I so admire and enjoy the original, this beautiful rendition popped to the top of my ratings screen, and it''s my personal favorite of the challenge.  This image has a softer feel, the colors blend and the atmosphere glows.  Like many other entries, it also has a hopeful, yearning mood, which is altogether appropriate.</td>', 'This image echoes Sherpet''s "Agave Blue" on her first profile page, so this is a very direct tribute.  Nevertheless, since I so admire and enjoy the original, this beautiful rendition popped to the top of my ratings screen, and it''s my personal favorite of the challenge.  This image has a softer feel, the colors blend and the atmosphere glows.  Like many other entries, it also has a hopeful, yearning mood, which is altogether appropriate.', '2018-05-10 21:58:45.000000', NULL, 1),
(7568213, 1214455, 173844, '<td valign="top">Both bold and delicate, the red leaf edges almost literally capture the viewer''s eye.  It''s a commanding, dramatic image that still displays an abundance of tonal variation.  I also like how it is subtly off-center.</td>', 'Both bold and delicate, the red leaf edges almost literally capture the viewer''s eye.  It''s a commanding, dramatic image that still displays an abundance of tonal variation.  I also like how it is subtly off-center.', '2018-05-10 22:04:37.000000', NULL, 1),
(7568214, 1214489, 173844, '<td valign="top">An intense blue that twilight brings to night, very stirring.  The composition also commands notice.  The lower right corner is not as compelling as the rest of the image.  I very much like the elegant simplicity that Sherpet also often strove for, the paring down of artistry to art.</td>', 'An intense blue that twilight brings to night, very stirring.  The composition also commands notice.  The lower right corner is not as compelling as the rest of the image.  I very much like the elegant simplicity that Sherpet also often strove for, the paring down of artistry to art.', '2018-05-10 22:11:08.000000', NULL, 1),
(7568216, 1214434, 173844, '<td valign="top">This is very much about narrow depth of field, and it succeeds grandly.  I find the moss of greater interest than the flowers, especially where they intermingle.  When I look at this from a distance greater than from chair to screen I like it more and more, as it becomes abstracted.  A very fine image.</td>', 'This is very much about narrow depth of field, and it succeeds grandly.  I find the moss of greater interest than the flowers, especially where they intermingle.  When I look at this from a distance greater than from chair to screen I like it more and more, as it becomes abstracted.  A very fine image.', '2018-05-10 22:17:46.000000', NULL, 1),
(7568217, 1214460, 173844, '<td valign="top">Terrific title for an image that knocks it out of the park.</td>', 'Terrific title for an image that knocks it out of the park.', '2018-05-10 22:19:01.000000', NULL, 1),
(7568218, 1214471, 173844, '<td valign="top">Not having looked through her entire portfolio, is this Sherpet-like?  In any case, I like this very much. It''s weirdly beautiful.  The colors and texture are, well, delicious.</td>', 'Not having looked through her entire portfolio, is this Sherpet-like?  In any case, I like this very much. It''s weirdly beautiful.  The colors and texture are, well, delicious.', '2018-05-10 22:22:05.000000', NULL, 1),
(7568219, 1214480, 173844, '<td valign="top">What a solid onion!  I''d like to see trees like this.  I like the sense of rigor and determination.  I also like the bokeh, which looks like a microscope slide of pond water.</td>', 'What a solid onion!  I''d like to see trees like this.  I like the sense of rigor and determination.  I also like the bokeh, which looks like a microscope slide of pond water.', '2018-05-10 22:25:25.000000', NULL, 1),
(7568220, 1214444, 173844, '<td valign="top">A rather startling take on Sherpet''s pencil fantasies, and I feel that this is a great tribute to her.  You''ve made her vision your own, with a wonderful twist sprung from your own vision.  The pattern varies in an interesting way, with the greens peeking through and a kind of wild texture overlay that somehow works.  Great image.</td>', 'A rather startling take on Sherpet''s pencil fantasies, and I feel that this is a great tribute to her.  You''ve made her vision your own, with a wonderful twist sprung from your own vision.  The pattern varies in an interesting way, with the greens peeking through and a kind of wild texture overlay that somehow works.  Great image.', '2018-05-10 22:41:11.000000', NULL, 1),
(7568221, 1214436, 173844, '<td valign="top">Wow, what a splashy flower!  I kind of feel like a deer transfixed by onrushing headlights --  not to minimize the tragic outcomes of such encounters.  This is as much a trumpet fanfare as a tribute, and sure to give Sherpet a smile.</td>', 'Wow, what a splashy flower!  I kind of feel like a deer transfixed by onrushing headlights --  not to minimize the tragic outcomes of such encounters.  This is as much a trumpet fanfare as a tribute, and sure to give Sherpet a smile.', '2018-05-10 22:49:30.000000', NULL, 1),
(7568224, 1214483, 173844, '<td valign="top">Lovely, glowing red flowers undiminished by the dusky speckling on the petals, maybe even enhanced by it.  Almost throbbing with life.  I like it as a valentine.</td>', 'Lovely, glowing red flowers undiminished by the dusky speckling on the petals, maybe even enhanced by it.  Almost throbbing with life.  I like it as a valentine.', '2018-05-10 22:55:52.000000', NULL, 1),
(7568225, 1214484, 173844, '<td valign="top">A touching, tender tribute, the love and yearning is palpable.  The fade-off in clarity is deftly achieved.  Simple and moving.</td>', 'A touching, tender tribute, the love and yearning is palpable.  The fade-off in clarity is deftly achieved.  Simple and moving.', '2018-05-10 23:01:04.000000', NULL, 1),
(7568227, 1214133, 185714, '<td valign="top">well spotted shadow</td>', 'well spotted shadow', '2018-05-10 23:02:16.000000', NULL, 1),
(7568229, 1214460, 185714, '<td valign="top">simply &amp; lovely. Sherpet''s style.</td>', 'simply & lovely. Sherpet''s style.', '2018-05-10 23:06:19.000000', NULL, 1),
(7568230, 1214217, 185714, '<td valign="top">Sherpet''s style. Nice</td>', 'Sherpet''s style. Nice', '2018-05-10 23:06:34.000000', NULL, 1),
(7568231, 1214453, 173844, '<td valign="top">One of the best tributes in the style of Sherpet.  The colors are vibrant and the composition is simple and strong.  This is as much an exploration as a depiction.  This is how a single flower can be a bouquet.</td>', 'One of the best tributes in the style of Sherpet.  The colors are vibrant and the composition is simple and strong.  This is as much an exploration as a depiction.  This is how a single flower can be a bouquet.', '2018-05-10 23:06:49.000000', NULL, 1),
(7568232, 1214446, 185714, '<td valign="top">Sherpet''s style. nice</td>', 'Sherpet''s style. nice', '2018-05-10 23:06:51.000000', NULL, 1),
(7568233, 1214277, 173844, '<td valign="top">This is so bright and cheerful.  The stamens (?) seem to wake up and dance.  Enchanting.  Coffee should look like this.</td>', 'This is so bright and cheerful.  The stamens (?) seem to wake up and dance.  Enchanting.  Coffee should look like this.', '2018-05-10 23:10:09.000000', NULL, 1),
(7568234, 1214438, 173844, '<td valign="top">Though I don''t really appreciate the swirly effect, the plants move well together and create an interesting pattern.</td>', 'Though I don''t really appreciate the swirly effect, the plants move well together and create an interesting pattern.', '2018-05-10 23:13:02.000000', NULL, 1),
(7568236, 1214466, 173844, '<td valign="top">I love the purple but feel that the olive-ish green doesn''t complement it well.  This is just a subjective take.  The blur does a fine job of abstraction.</td>', 'I love the purple but feel that the olive-ish green doesn''t complement it well.  This is just a subjective take.  The blur does a fine job of abstraction.', '2018-05-10 23:17:10.000000', NULL, 1),
(7568237, 1214339, 68504, '<td valign="top">I enjoy this photo with nostalgia and a dreamy kind of yearning.</td>', 'I enjoy this photo with nostalgia and a dreamy kind of yearning.', '2018-05-10 23:19:09.000000', NULL, 1),
(7568238, 1214459, 173844, '<td valign="top">Very bizarre image, kind of surreal.  The beautiful, creamy white flower and the startling beetle are just so startling.  Great vignette.  I like it.</td>', 'Very bizarre image, kind of surreal.  The beautiful, creamy white flower and the startling beetle are just so startling.  Great vignette.  I like it.', '2018-05-10 23:21:08.000000', NULL, 1),
(7568239, 1214133, 68504, '<td valign="top">nice transposition of Sherpetry.</td>', 'nice transposition of Sherpetry.', '2018-05-10 23:22:12.000000', NULL, 1),
(7568240, 1214459, 68504, '<td valign="top">love the freestyle loud drama.</td>', 'love the freestyle loud drama.', '2018-05-10 23:23:58.000000', NULL, 1),
(7568241, 1214449, 173844, '<td valign="top">Lovely flower macro that''s hard not to anthropomorphize.  The tones are very delicate and inviting.  The blue in the upper right corner is distracting.</td>', 'Lovely flower macro that''s hard not to anthropomorphize.  The tones are very delicate and inviting.  The blue in the upper right corner is distracting.', '2018-05-10 23:25:12.000000', NULL, 1),
(7568242, 1214435, 173844, '<td valign="top">Pretty group of flowers that seem to be emerging from the frame, coming over to join us.  At the same time the delicate pinks are visually soothing.</td>', 'Pretty group of flowers that seem to be emerging from the frame, coming over to join us.  At the same time the delicate pinks are visually soothing.', '2018-05-10 23:28:41.000000', NULL, 1),
(7568243, 1214342, 173844, '<td valign="top">A good tribute featuring the majestic beauty of this plant.  Color and form here are everything.</td>', 'A good tribute featuring the majestic beauty of this plant.  Color and form here are everything.', '2018-05-10 23:31:28.000000', NULL, 1),
(7568244, 1214339, 173844, '<td valign="top">Nicely composed with an interesting sky.  The atmosphere is soft and dreamy.  My only quibble is that I''d like to see the top of the tree, though maybe this is an artistic choice.</td>', 'Nicely composed with an interesting sky.  The atmosphere is soft and dreamy.  My only quibble is that I''d like to see the top of the tree, though maybe this is an artistic choice.', '2018-05-10 23:34:35.000000', NULL, 1),
(7568245, 1214343, 173844, '<td valign="top">A very Sherpet-like tribute.  Nice colors and sea-life.</td>', 'A very Sherpet-like tribute.  Nice colors and sea-life.', '2018-05-10 23:37:37.000000', NULL, 1),
(7568246, 1214428, 173844, '<td valign="top">Interesting thought.  The flowers are like a bonnet and the clouds swimming in the sky are charming.</td>', 'Interesting thought.  The flowers are like a bonnet and the clouds swimming in the sky are charming.', '2018-05-10 23:40:33.000000', NULL, 1),
(7568247, 1214450, 173844, '<td valign="top">Fascinating image.  The shallow focus works well.  Though I''m not sure what to make of it, I like this a lot.</td>', 'Fascinating image.  The shallow focus works well.  Though I''m not sure what to make of it, I like this a lot.', '2018-05-10 23:44:39.000000', NULL, 1),
(7568248, 1214465, 173844, '<td valign="top">Elegant study.</td>', 'Elegant study.', '2018-05-10 23:45:07.000000', NULL, 1),
(7568249, 1214217, 173844, '<td valign="top">A touching tribute.</td>', 'A touching tribute.', '2018-05-10 23:45:47.000000', NULL, 1),
(7568250, 1214474, 173844, '<td valign="top">A pretty tribute that also looks like a memorial flame.</td>', 'A pretty tribute that also looks like a memorial flame.', '2018-05-10 23:47:00.000000', NULL, 1),
(7568251, 1214473, 173844, '<td valign="top">Simple and thoughtful.  I love the golden bokeh.</td>', 'Simple and thoughtful.  I love the golden bokeh.', '2018-05-10 23:48:06.000000', NULL, 1),
(7568252, 1214448, 185714, '<td valign="top">Sherpet''s style. Nice execution in color tones.</td>', 'Sherpet''s style. Nice execution in color tones.', '2018-05-11 00:05:32.000000', NULL, 1),
(7568253, 1214455, 185714, '<td valign="top">lovely details</td>', 'lovely details', '2018-05-11 00:06:09.000000', NULL, 1),
(7568254, 1214466, 185714, '<td valign="top">Sherpet''s style of blur.</td>', 'Sherpet''s style of blur.', '2018-05-11 00:10:18.000000', NULL, 1),
(7568256, 1214453, 185714, '<td valign="top">Sherpet''s style.  Lovely</td>', 'Sherpet''s style.  Lovely', '2018-05-11 00:11:34.000000', NULL, 1),
(7568257, 1214460, 97225, '<td valign="top">Beautiful and so very Sherpet!</td>', 'Beautiful and so very Sherpet!', '2018-05-11 00:18:17.000000', NULL, 1),
(7568258, 1214453, 97225, '<td valign="top">Lovely tribute to Shez.</td>', 'Lovely tribute to Shez.', '2018-05-11 00:57:16.000000', NULL, 1),
(7568259, 1214088, 97225, '<td valign="top">Beautifully done tribute to Shez, Top few.</td>', 'Beautifully done tribute to Shez, Top few.', '2018-05-11 00:57:43.000000', NULL, 1),
(7568260, 1214484, 97225, '<td valign="top">This is really lovely. Shez would have loved it.</td>', 'This is really lovely. Shez would have loved it.', '2018-05-11 00:58:16.000000', NULL, 1),
(7568261, 1214217, 97225, '<td valign="top">Lovely and a very fitting tribute.</td>', 'Lovely and a very fitting tribute.', '2018-05-11 00:58:56.000000', NULL, 1),
(7568262, 1214455, 97225, '<td valign="top">Lovely tribute to Shez.</td>', 'Lovely tribute to Shez.', '2018-05-11 00:59:15.000000', NULL, 1),
(7568263, 1214343, 97225, '<td valign="top">Shez would have loved this. Top few.</td>', 'Shez would have loved this. Top few.', '2018-05-11 00:59:45.000000', NULL, 1),
(7568266, 1214484, 97225, '<td valign="top">Not only would Shez have loved this, I do too. I was your 10 - such a last second bump up that I didn''t know whether it would stick but it did.</td>', 'Not only would Shez have loved this, I do too. I was your 10 - such a last second bump up that I didn''t know whether it would stick but it did.', '2018-05-11 01:04:22.000000', NULL, 0),
(7568267, 1214448, 97225, '<td valign="top">Congratulations Wendy. A great tribute to Shez, beautifully done.</td>', 'Congratulations Wendy. A great tribute to Shez, beautifully done.', '2018-05-11 01:08:58.000000', NULL, 0),
(7568268, 1214435, 3306, '<td valign="top">Congrats on 4th. My top 2 pick. Just beautiful.</td>', 'Congrats on 4th. My top 2 pick. Just beautiful.', '2018-05-11 01:10:22.000000', NULL, 0),
